anuelle/Xun (Bagua)|qq=}} | style="background:green;color:white;" |Green |- !{{ill|Fifth Yellow Earth Star|1=Fifth Yellow Earth Star|ja|五黄土星|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Fifth Yellow Earth Star|13=User:Immanuelle/Fifth Yellow Earth Star|qq=}} |Goō Dosei |Earth |Center |{{ill|Taiji (philosophy)|lt=Taiji|ja|太極|fr|Taiji (philosophie)|ru|Великий предел|ja|太極|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Taiji (philosophy)|qq=}} | style="background:yellow;" |Yellow |- !{{ill|Sixth White Metal Star|1=Sixth White Metal Star|ja|六白金星|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Sixth White Metal Star|13=User:Immanuelle/Sixth White Metal Star|qq=}} |Roppaku Kinsei |Metal |Northwest |{{ill|Qian|ja|乾|1=Qian (Bagua)|2=ja|3=乾|lt=Qian (乾)|1=Qian (Bagua)|lt=Qian|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Qian|13=User:Immanuelle/Qian (Bagua)|qq=}} | style="background:white;" |White |- !{{ill|Seventh Red Metal Star|1=Seventh Red Metal Star|ja|七赤金星|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Seventh Red Metal Star|13=User:Immanuelle/Seventh Red Metal Star|qq=}} |Shichiseki Kinsei |Metal |{{ill|West|ja|西|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/West|qq=}} |{{ill|Dui|ja|兌|1=Dui (Bagua)|2=ja|3=兌|4=zh-yue|5=兌卦|6=ko|7=태 (괘)|8=fr|9=Duì|10=nl|11=Meer (trigram)|12=pt|13=Duì (I Ching)|14=zh-min-nan|15=Tōe-kòa|lt=Dui (兌)|1=Dui (Bagua)|lt=Dui|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Dui|13=User:Immanuelle/Dui (Bagua)|qq=}} | style="background:red;color:white;" |Red |- !{{ill|Eighth White Earth Star|1=Eighth White Earth Star|ja|八白土星|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Eighth White Earth Star|13=User:Immanuelle/Eighth White Earth Star|qq=}} |Happaku Dosei |Earth |Northeast |{{ill|Gen|ja|艮|1=Gen (Bagua)|2=ja|3=艮|lt=Gen (艮)|1=Gen (Bagua)|lt=Gen|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Gen|13=User:Immanuelle/Gen (Bagua)|qq=}} | style="background:white;" |White |- !{{ill|Ninth Purple Fire Star|1=Ninth Purple Fire Star|ja|九紫火星|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Ninth Purple Fire Star|13=User:Immanuelle/Ninth Purple Fire Star|qq=}} |Kyūshi Kasei |Fire |{{ill|South|ja|南|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/South|qq=}} |{{ill|Li|ja|離|1=Li (Bagua)|lt=Li|qq=draft|qq=|qq=draft|12=simple|13=User:Immanuelle/Li|13=User:Immanuelle/Li (Bagua)|qq=}} | style="background:purple;color:white;" |Purple |}
